CREATE TEMP TABLE before_descriptions AS SELECT c.relname,a.attname,col_description(c.oid,a.attnum) AS description FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_attribute a ON a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped WHERE n.nspname='public';
\ir ../migrations/20261019000921_describe_queued_columns.sql
DO $coverage$ BEGIN
 IF (SELECT count(*) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND a.attnum>0 AND NOT a.attisdropped) <> 449 THEN RAISE EXCEPTION 'column shape changed'; END IF;
 IF (SELECT count(*) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND a.attnum>0 AND NOT a.attisdropped AND col_description(c.oid,a.attnum) IS NOT NULL) <> 449 THEN RAISE EXCEPTION 'missing column description'; END IF;
 IF EXISTS (SELECT 1 FROM before_descriptions b WHERE b.description IS NOT NULL AND NOT (b.relname='vehicle_custom_circuits' AND b.attname='derivation_version') AND col_description(('public.'||quote_ident(b.relname))::regclass,(SELECT a.attnum FROM pg_attribute a WHERE a.attrelid=('public.'||quote_ident(b.relname))::regclass AND a.attname=b.attname)) IS DISTINCT FROM b.description) THEN RAISE EXCEPTION 'existing non-target description changed'; END IF;
 RAISE NOTICE '449 column shapes and descriptions qualified; existing non-target comments preserved';
END $coverage$;
CREATE TEMP TABLE descriptions_after AS SELECT c.relname,a.attname,col_description(c.oid,a.attnum) AS description FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_attribute a ON a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped WHERE n.nspname='public';
\ir ../migrations/20261019000921_describe_queued_columns.sql
DO $repeat$ BEGIN
 IF EXISTS (SELECT 1 FROM descriptions_after b WHERE col_description(('public.'||quote_ident(b.relname))::regclass,(SELECT a.attnum FROM pg_attribute a WHERE a.attrelid=('public.'||quote_ident(b.relname))::regclass AND a.attname=b.attname)) IS DISTINCT FROM b.description) THEN RAISE EXCEPTION 'repeat changed a description'; END IF;
 RAISE NOTICE 'repeat migration preserves every resulting description';
END $repeat$;
